def f(g):
    import numpy as np
    a=np.array(g); h,w=a.shape
    # segment in row 0
    cols=[c for c in range(w) if a[0,c]!=0]
    seg={a[0,c]:c for c in cols}
    out=a.copy()
    singles={}
    for r in range(h):
        for c in range(w):
            if a[r,c]!=0 and r>0: singles[a[r,c]]=(r,c)
    for color,c in seg.items():
        if color in singles:
            r,_=singles[color]
        else:
            r=h-1
        for rr in range(0,r+1): out[rr,c]=color
    for color,(r,c) in singles.items():
        sc=seg[color]
        for cc in range(min(c,sc),max(c,sc)+1): out[r,cc]=color
    return out.tolist()

